caught:=false; BEGIN UPDATE public."Payments" SET "Ref Target Charge"='__FK_TEST_MISSING_PARENT__' WHERE "Row ID"=k; EXCEPTION WHEN foreign_key_violation THEN caught:=true; END; IF NOT caught THEN RAISE EXCEPTION 'Invalid reference accepted: appsheet_ref_13'; END IF;
