caught:=false; BEGIN INSERT INTO public."Payments" SELECT (jsonb_populate_record(NULL::public."Payments",to_jsonb(c)||jsonb_build_object('Row ID','__FK_PROBE_appsheet_ref_13__','Ref Target Charge','__FK_TEST_MISSING_PARENT__'))).* FROM public."Payments" c WHERE c."Row ID"=k; EXCEPTION WHEN foreign_key_violation THEN caught:=true; END; IF NOT caught THEN RAISE EXCEPTION 'Invalid insert accepted: appsheet_ref_13'; END IF;
END $test$; SELECT 'passed' AS foreign_key_tests,91 AS checks;